window.kbPageData["views/entry/k-cd75d494b9976679"] = {"key":"entry/k-cd75d494b9976679","state":{"route":"entry/k-cd75d494b9976679"},"node":{"id":"k-cd75d494b9976679","mode":"k","title":"民事裁判的事实依据","type":"制度与规则","domain":"法律","reading":"","intro":"","priority":100,"aliases":["民事裁判以证据能够证明的案件事实为根据"],"qs":["江苏 2025 B类 行测#16"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"人民法院审理民事案件，应当以证据能够证明的案件事实为根据依法作出裁判。待证事实无法认定时，依法适用举证责任规则确定相应后果。","review":{"definition":"人民法院审理民事案件，应当以证据能够证明的案件事实为根据依法作出裁判。待证事实无法认定时，依法适用举证责任规则确定相应后果。","explanation":"第16题B项认为事实无法查清时法院就不应作出终局裁判。以民事诉讼为例，法院可以根据已经证明的事实及举证责任规则作出裁判，因此B项把事实认定上的困难写成了终局裁判的障碍。","references":[],"evidence":"人民法院应当以证据能够证明的案件事实为根据依法作出裁判。","disposition":"独立词条","basis":"据原题和解析编释。"}},"questions":{"江苏 2025 B类 行测#16":{"paper":"江苏 2025 B类 行测","n":16,"mod":"常识判断","src":["91e0d9fd02ca7ec6d61f.pdf",4],"asrc":["f2ff67a0f2a2f7e8e926.pdf",6],"card":"e4d47d034c952b8ddf91e4bf","links":[{"id":"k-cd75d494b9976679","role":"解题依据","why":"证据裁判规则说明，法院仍可根据已经证明的事实作出裁判。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-cd75d494b9976679":[["江苏 2025 B类 行测#16"]]}};
